def validate_iban(iban: str) -> bool:
    if not isinstance(iban, str):
        return False
    try:
        normalized = normalize_iban(iban)
    except ValueError:
        return False
    lengths = {
        "AD": 24,
        "AT": 20,
        "BE": 16,
        "CH": 21,
        "DE": 22,
        "ES": 24,
        "FR": 27,
        "GB": 22,
        "IE": 22,
        "IT": 27,
        "LU": 20,
        "NL": 18,
        "NO": 15,
        "PL": 28,
        "PT": 25,
        "SE": 24,
    }
    # Need at least country + check digits.
    if len(normalized) < 4:
        return False
    country = normalized[:2]
    if country not in lengths:
        return False
    if len(normalized) != lengths[country]:
        return False
    # Structure: 1-2 letters, 3-4 digits, rest alphanumeric.
    for c in normalized[:2]:
        if not ("A" <= c <= "Z"):
            return False
    for c in normalized[2:4]:
        if not ("0" <= c <= "9"):
            return False
    for c in normalized[4:]:
        if not (("A" <= c <= "Z") or ("0" <= c <= "9")):
            return False
    # Mod-97 check.
    try:
        rearranged = normalized[4:] + normalized[:4]
        parts = []
        for c in rearranged:
            if "0" <= c <= "9":
                parts.append(c)
            else:
                parts.append(str(ord(c) - 55))
        digit_string = "".join(parts)
        if int(digit_string) % 97 != 1:
            return False
    except Exception:
        return False
    return True


def normalize_iban(iban: str) -> str:
    if not isinstance(iban, str):
        raise ValueError("iban must be a string")
    return iban.replace(" ", "").upper()
